beforeExample:
public class Example {
    public int calculate(int charWidth, int singleCharWidth) {
        // Original code suffers from integer division before Math.ceil
        return (int)Math.ceil(charWidth / singleCharWidth);
    }

    public int calculateWithError(int a, int b) {
        return (int) Math.ceil(a / b);
    }
}

afterExample:
public class Example {
    public int calculate(int charWidth, int singleCharWidth) {
        // Corrected to ensure floating-point division
        return (int)Math.ceil((double) charWidth / singleCharWidth);
    }

    public int calculateWithError(int a, int b) {
        return (int) Math.ceil((double) a / b);
    }
}

negativeExample:
public class Example {
    public int calculate(double charWidth, int singleCharWidth) {
        // Already uses double division, no change needed
        return (int)Math.ceil(charWidth / singleCharWidth);
    }

    public double anotherCalculation(int val) {
        // Math.ceil not cast to int
        return Math.ceil(val / 2);
    }
}
